create table public.serial_reservations(id uuid primary key default gen_random_uuid(),staff_id uuid not null references public.staff(id) on delete cascade,variant_id uuid not null references public.product_variants(id),serial_id uuid not null unique references public.product_serials(id),created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '30 minutes'),unique(staff_id,serial_id));
alter table public.serial_reservations enable row level security;
create policy serial_reservations_own on public.serial_reservations for select to authenticated using(staff_id=private.auth_staff_id() or private.auth_is_admin());
create or replace function public.reservar_seriales_carrito(p_variant_id uuid,p_serial_ids jsonb) returns integer language plpgsql security definer set search_path='public','private' as $$declare s public.staff;sid text;n int:=0;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null then raise exception 'Personal inválido';end if;delete from public.serial_reservations where staff_id=s.id and variant_id=p_variant_id;for sid in select jsonb_array_elements_text(coalesce(p_serial_ids,'[]'::jsonb)) loop if not exists(select 1 from public.product_serials where id=sid::uuid and variant_id=p_variant_id and location_id=s.location_id and estado='disponible') then raise exception 'Serial no disponible';end if;insert into public.serial_reservations(staff_id,variant_id,serial_id) values(s.id,p_variant_id,sid::uuid);n:=n+1;end loop;return n;end$$;
create or replace function public.liberar_seriales_carrito(p_variant_id uuid) returns boolean language plpgsql security definer set search_path='public','private' as $$begin delete from public.serial_reservations where staff_id=private.auth_staff_id() and variant_id=p_variant_id;return true;end$$;
grant execute on function public.reservar_seriales_carrito(uuid,jsonb) to authenticated;
grant execute on function public.liberar_seriales_carrito(uuid) to authenticated;
create or replace function private.asignar_seriales_venta() returns trigger language plpgsql security definer set search_path='public','private' as $$declare v_control boolean;v_sale public.sales;v_count int;r record;begin select p.control_serial into v_control from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=new.variant_id;if not coalesce(v_control,false) then return new;end if;select * into v_sale from public.sales where id=new.sale_id;delete from public.serial_reservations where expires_at<now();select count(*) into v_count from public.serial_reservations sr join public.product_serials ps on ps.id=sr.serial_id where sr.staff_id=v_sale.cajero_id and sr.variant_id=new.variant_id and ps.location_id=v_sale.location_id and ps.estado='disponible';if v_count<>new.cantidad then raise exception 'Selecciona exactamente % IMEI/serie(s) disponibles antes de cobrar',new.cantidad;end if;for r in select sr.id reservation_id,ps.id serial_id from public.serial_reservations sr join public.product_serials ps on ps.id=sr.serial_id where sr.staff_id=v_sale.cajero_id and sr.variant_id=new.variant_id and ps.location_id=v_sale.location_id and ps.estado='disponible' order by sr.created_at limit new.cantidad loop update public.product_serials set estado='vendido',sale_id=v_sale.id,sold_at=now(),updated_at=now() where id=r.serial_id;insert into public.sale_item_serials(sale_item_id,serial_id) values(new.id,r.serial_id);delete from public.serial_reservations where id=r.reservation_id;end loop;return new;end$$;
drop trigger if exists trg_asignar_seriales_venta on public.sale_items;
create trigger trg_asignar_seriales_venta after insert on public.sale_items for each row execute function private.asignar_seriales_venta();
revoke all on function private.asignar_seriales_venta() from public,anon,authenticated;
create or replace function public.registrar_venta_serializada(p_items jsonb,p_pagos jsonb,p_subtotal numeric,p_impuesto numeric,p_total numeric,p_client_transaction_id uuid default null,p_cliente_id uuid default null,p_cliente_doc text default null,p_location_id uuid default null,p_cajero_id uuid default null,p_cash_session_id uuid default null,p_tipo_comprobante text default 'boleta',p_comprobante_cliente_tipo_doc text default null,p_comprobante_cliente_num_doc text default null,p_comprobante_cliente_denominacion text default null,p_comprobante_cliente_direccion text default null) returns public.sales language plpgsql security definer set search_path='public','private' as $$declare x jsonb;v_control boolean;v_serials jsonb;v_staff uuid;begin v_staff:=private.auth_staff_id();for x in select * from jsonb_array_elements(p_items) loop select p.control_serial into v_control from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=(x->>'variant_id')::uuid;if coalesce(v_control,false) then v_serials:=coalesce(x->'serial_ids','[]'::jsonb);perform public.reservar_seriales_carrito((x->>'variant_id')::uuid,v_serials);end if;end loop;return public.registrar_venta(p_items,p_pagos,p_subtotal,p_impuesto,p_total,p_client_transaction_id,p_cliente_id,p_cliente_doc,p_location_id,p_cajero_id,p_cash_session_id,p_tipo_comprobante,p_comprobante_cliente_tipo_doc,p_comprobante_cliente_num_doc,p_comprobante_cliente_denominacion,p_comprobante_cliente_direccion);end$$;